.elementor-1274{max-width:none;margin:0;padding:0}
.elementor-1274{--jb-navy:#122e43;--jb-ink:#223747;--jb-blue:#236b9c;--jb-sky:#86cef7;--jb-muted:#657783;--jb-line:#e1eaf0;--jb-paper:#f4f8fb;--jb-radius:12px;--jb-max:1350px;--jb-gutter:20px;background:white;color:var(--jb-ink);font-family:'Segoe UI','Nirmala UI','Noto Sans Bengali',Arial,sans-serif;line-height:1.85;-webkit-font-smoothing:antialiased}
