.elementor-1274 svg{flex-shrink:0}
.elementor-1274 img{display:block;width:100%;max-width:100%;object-fit:cover}
.elementor-1274 h1,.elementor-1274 h2,.elementor-1274 h3,.elementor-1274 p{font-family:inherit;color:inherit;padding:0;margin:0}
